import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { supabaseService } from '../../../services/supabaseService';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import Input from '../../../components/ui/Input';
import { useToast } from '../../../contexts/ToastContext';

const MfaSettings = ({ onStatusChange }) => {
    const { user } = useSelector((state) => state.auth);
    const [factors, setFactors] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isEnrolling, setIsEnrolling] = useState(false);
    const [qrCode, setQrCode] = useState('');
    const [mfaSecret, setMfaSecret] = useState('');
    const [verifyCode, setVerifyCode] = useState('');
    const [factorId, setFactorId] = useState(null);
    const [backupCodes, setBackupCodes] = useState([]);
    const [showBackupCodes, setShowBackupCodes] = useState(false);
    const { addToast } = useToast();

    useEffect(() => {
        loadFactors();
    }, []);

    const loadFactors = async () => {
        try {
            const data = await supabaseService.getMfaFactors();
            const loadedFactors = data.totp || [];
            setFactors(loadedFactors);
            if (onStatusChange) {
                onStatusChange(loadedFactors.some(f => f.status === 'verified'));
            }
        } catch (error) {
            console.error('Error loading MFA factors:', error);
            addToast('Failed to load security settings', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const handleEnroll = async () => {
        setIsEnrolling(true);
        try {
            // Clean up any stale unverified factors first (can block new enrollment)
            const existingData = await supabaseService.getMfaFactors();
            const unverified = (existingData.totp || []).filter(f => f.status !== 'verified');
            for (const f of unverified) {
                try { await supabaseService.unenrollMfa(f.id); } catch (_) { /* ignore */ }
            }
            const data = await supabaseService.enrollMfa();
            setFactorId(data.id);
            setQrCode(data.totp.qr_code);
            setMfaSecret(data.totp.secret);
        } catch (error) {
            console.error('Error enrolling MFA:', error);
            addToast('Failed to start MFA enrollment', 'error');
            setIsEnrolling(false);
        }
    };


    const handleVerify = async (codeStr) => {
        const codeToVerify = typeof codeStr === 'string' ? codeStr : verifyCode;
        if (codeToVerify.length < 6) return addToast('Enter the full 6-digit code', 'warning');
        try {
            await supabaseService.challengeAndVerifyMfaEnrollment(factorId, codeToVerify);
            
            // Generate backup codes immediately
            try {
                const codes = await supabaseService.generateBackupCodes(user.id);
                setBackupCodes(codes);
                setShowBackupCodes(true);
            } catch (err) {
                console.error("Backup code generation failed", err);
            }

            addToast('Multi-Factor Authentication enabled successfully!', 'success');
            setQrCode('');
            setMfaSecret('');
            setVerifyCode('');
            setFactorId(null);
            setIsEnrolling(false);
            loadFactors();
        } catch (error) {
            console.error('Error verifying MFA:', error);
            addToast('Invalid verification code. Please try again.', 'error');
        }
    };

    const handleUnenroll = async (id) => {
        if (!window.confirm('Are you sure you want to disable MFA? This drastically decreases your account security.')) return;
        try {
            await supabaseService.unenrollMfa(id);
            addToast('MFA disabled successfully.', 'success');
            loadFactors();
        } catch (error) {
            console.error('Error unenrolling MFA:', error);
            addToast('Failed to disable MFA', 'error');
        }
    };

    if (isLoading) return <div className="text-sm text-muted-foreground flex items-center gap-2"><Icon name="RefreshCw" className="animate-spin" size={16} /> Loading security status...</div>;

    if (showBackupCodes) {
        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 text-center">
                <div className="w-16 h-16 bg-emerald-500/10 rounded-full flex items-center justify-center mx-auto text-emerald-500 mb-4">
                    <Icon name="ShieldCheck" size={32} />
                </div>
                <h3 className="text-xl font-black italic uppercase tracking-tight">Security Protocol Established</h3>
                <p className="text-sm text-muted-foreground font-medium italic">
                    Multi-Factor Authentication is active. Please <strong className="text-foreground">download or copy</strong> these recovery codes. They are the ONLY way to regain access if you lose your authenticator device.
                </p>

                <div className="grid grid-cols-2 gap-2 bg-muted/30 p-4 rounded-2xl border border-border font-mono text-xs tracking-widest">
                    {backupCodes.map((code, i) => (
                        <div key={i} className="p-2 bg-background rounded-lg border border-border select-all">{code}</div>
                    ))}
                </div>

                <div className="flex flex-col gap-3">
                    <Button 
                        variant="primary" 
                        onClick={() => {
                            const blob = new Blob([backupCodes.join('\n')], { type: 'text/plain' });
                            const url = URL.createObjectURL(blob);
                            const a = document.createElement('a');
                            a.href = url;
                            a.download = `LUC-recovery-codes-${user?.email}.txt`;
                            a.click();
                        }}
                        className="w-full h-12 rounded-xl font-black italic uppercase text-xs tracking-widest"
                    >
                        <Icon name="Download" size={16} className="mr-2" /> DOWNLOAD CODES
                    </Button>
                    <Button 
                        variant="ghost" 
                        onClick={() => setShowBackupCodes(false)}
                        className="w-full h-10 rounded-xl font-black italic uppercase text-[10px] tracking-widest opacity-60"
                    >
                        I HAVE SAVED THESE CODES
                    </Button>
                </div>
            </div>
        );
    }

    const activeFactors = factors.filter(f => f.status === 'verified');

    return (
        <div className="space-y-4 w-full">
            {activeFactors.length > 0 ? (
                <div className="space-y-3">
                    {activeFactors.map(factor => (
                        <div key={factor.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-xl gap-4">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center text-emerald-500 shrink-0">
                                    <Icon name="ShieldCheck" size={20} />
                                </div>
                                <div>
                                    <p className="text-sm font-bold text-emerald-600">Authenticator App Enabled</p>
                                    <p className="text-[10px] text-emerald-600/70">Added {new Date(factor.created_at).toLocaleDateString()}</p>
                                </div>
                            </div>
                            <Button variant="outline" size="sm" className="text-red-500 border-red-500/20 hover:bg-red-500 hover:text-white" onClick={() => handleUnenroll(factor.id)}>
                                Disable MFA
                            </Button>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="bg-muted/10 border border-border rounded-xl">
                    {!isEnrolling ? (
                        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4">
                            <div>
                                <p className="text-sm font-bold text-primary">Two-Factor Authentication (TOTP)</p>
                                <p className="text-xs text-muted-foreground mt-1 max-w-md">
                                    Add an extra layer of security to your account. You'll need to enter a code from an authenticator app (like Google Authenticator or Authy) to sign in.
                                </p>
                            </div>
                            <Button onClick={handleEnroll} variant="outline" className="text-emerald-500 border-emerald-500/20 hover:bg-emerald-500 hover:text-white shrink-0">
                                Enable MFA
                            </Button>
                        </div>
                    ) : (
                        <div className="p-6 space-y-6 animate-in fade-in zoom-in duration-300">
                            <div className="flex items-center gap-2">
                                <Icon name="Smartphone" className="text-primary" size={20} />
                                <h4 className="font-bold text-primary">Configure Authenticator App</h4>
                            </div>
                            <p className="text-sm text-muted-foreground">
                                1. Open your authenticator app.<br/>
                                2. Scan the QR code below.
                            </p>
                            <div className="bg-white p-4 rounded-xl w-fit border-4 border-muted/50 mx-auto" dangerouslySetInnerHTML={{ __html: qrCode }} />
                            
                            <div className="text-center mt-2">
                                <p className="text-xs text-muted-foreground mb-1">Or enter this setup key manually:</p>
                                <div className="bg-muted p-2 rounded-lg text-xs font-mono tracking-widest break-all select-all border border-border">
                                    {mfaSecret}
                                </div>
                            </div>

                            <p className="text-sm text-muted-foreground mt-4">
                                3. Enter the 6-digit code generated by the app to verify.
                            </p>
                            <div className="flex items-center gap-3 max-w-xs">
                                <Input 
                                    placeholder="000000" 
                                    maxLength={6} 
                                    value={verifyCode} 
                                    onChange={(e) => {
                                        const val = e.target.value.replace(/\D/g, '');
                                        setVerifyCode(val);
                                        if (val.length === 6) {
                                            handleVerify(val);
                                        }
                                    }}
                                    className="text-center tracking-widest font-mono text-lg flex-1"
                                />
                                <Button onClick={handleVerify} size="lg">Verify</Button>
                            </div>
                            <div className="pt-2">
                                <Button variant="ghost" size="sm" onClick={() => setIsEnrolling(false)}>Cancel Setup</Button>
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default MfaSettings;
